const input = $json.body ?? $json;
const target = input.target_url ?? input.url ?? input.target ?? '';
const task = input.task ?? input.chatInput ?? input.message ?? '';
const sessionId = input.session_id ?? input.sessionId ?? `session-${Date.now()}`;
const scopeToken = input.scope_token ?? '';
const expectedToken = $env.CTF_SCOPE_TOKEN;

if (!target) throw new Error('Missing target_url.');
if (!/^https?:\/\//i.test(target)) throw new Error('target_url must use http:// or https://.');
if (expectedToken && scopeToken !== expectedToken) throw new Error('Unauthorized CTF scope.');
if (target.length > 2048) throw new Error('target_url is too long.');

return [{ json: { target_url: target, task: task || 'Analyze the authorized CTF target and capture the flag.', session_id: String(sessionId), scope_validated: true } }];

const target = $json.target_url;
const task = $json.task;
return [{ json: { ...$json, prompt: `You are solving an authorized web CTF challenge. Target: ${target}

Task: ${task}

Rules: work only against the supplied authorized CTF target; do not attack unrelated systems; do not use sqlite3; use the available Kali command and Python tools; inspect command output carefully; stop when the flag is found; report the exact evidence and commands used.` } }];

const flag = String($json.output?.Flag ?? '').trim();
const description = String($json.output?.description ?? '').trim();
return [{ json: { flag, description, flag_found: Boolean(flag), timestamp: new Date().toISOString() } }];
